<?php
/**
 * Fonctions utilitaires pour le filemanager ZwiiCMS
 * Gestion de la lecture des fichiers JsonDb (compression + cryptage)
 */
function readUserJsonFile($filePath) { $content = file_get_contents($filePath); if ($content === false) { return null; } $decoded = json_decode($content, true); if (is_array($decoded)) { $data = $decoded; } else { $isCompressed = (substr($content, 0, 2) === "\x78\x9c" || substr($content, 0, 2) === "\x78\xda" || substr($content, 0, 2) === "\x78\x5e"); if ($isCompressed) { $decompressed = gzuncompress($content); if ($decompressed !== false) { $data = json_decode($decompressed, true); } else { return null; } } else { return null; } } if (isset($data['encrypted']) && $data['encrypted'] === true) { $configPath = '../../../site/data/config.json'; $configContent = file_get_contents($configPath); if ($configContent === false) { return null; } $configDecoded = json_decode($configContent, true); if (!is_array($configDecoded)) { $isConfigCompressed = (substr($configContent, 0, 2) === "\x78\x9c" || substr($configContent, 0, 2) === "\x78\xda" || substr($configContent, 0, 2) === "\x78\x5e"); if ($isConfigCompressed) { $configDecompressed = gzuncompress($configContent); if ($configDecompressed !== false) { $configData = json_decode($configDecompressed, true); } else { return null; } } else { return null; } } else { $configData = $configDecoded; } $encryptionKey = $configData['config']['database']['user']['encryptionKey'] ?? null; $userEncryption = $configData['config']['database']['user']['encryption'] ?? false; if ($encryptionKey && isset($data['data'])) { $encryptedData = base64_decode($data['data']); $iv = substr($encryptedData, 0, 16); $encrypted = substr($encryptedData, 16); $decrypted = openssl_decrypt( $encrypted, 'AES-256-CBC', $encryptionKey, OPENSSL_RAW_DATA, $iv ); if ($decrypted !== false) { $data = json_decode($decrypted, true); } else { return null; } } } return $data; }
